function execute_sanitize_js_file(params) {
  try {
    // Validate parameters
    if (!params || typeof params.filePath !== 'string' || typeof params.fileContent !== 'string') {
      return { success: false, error: 'params.filePath and params.fileContent are required' };
    }

    // ---------- Step 1: Trim trailing spaces ----------
    const trimmedContent = params.fileContent.replace(/[ \t]+$/gm, '');

    // ---------- Step 2: Add missing semicolons ----------
    const lines = trimmedContent.split('\n');
    const semicolonedLines = lines.map(line => {
      const trimmed = line.trimEnd();

      // Skip if line already ends with a semicolon, brace, or starts with a control keyword
      if (trimmed.endsWith(';') || trimmed.endsWith('}') || trimmed.endsWith('{') ||
          /^\s*(if|for|while|import|export)\b/.test(trimmed) ||
          /^\s*(\/\/|\/\*|\*\/)/.test(trimmed)) {
        return trimmed;
      }

      // Simple heuristic for expressions or assignments
      const hasAssignment = /[^=!<>]=[^=]|=.+$/.test(trimmed);
      const endsWithExpr = hasAssignment || /\w$/.test(trimmed);

      return endsWithExpr ? trimmed + ';' : trimmed;
    });

    // ---------- Step 3: Collapse long string literals ----------
    const collapsedLines = semicolonedLines.map(line => {
      // Find all string literals (single or double quoted)
      const stringRegex = /(['"])((?:\\.|[^\\])*?)\1/g;
      return line.replace(stringRegex, (match, quote, inside) => {
        if (inside.length <= 80) return match;
        const parts = [];
        for (let i = 0; i < inside.length; i += 80) {
          parts.push(inside.slice(i, i + 80));
        }
        let replaced = parts[0];
        for (let i = 1; i < parts.length; i++) {
          replaced += ' + ' + quote + parts[i] + quote;
        }
        return quote + replaced + quote;
      });
    });

    const cleanedContent = collapsedLines.join('\n');

    // ---------- Step 4: Compute new file path ----------
    const filePath = params.filePath;
    const lastSlash = Math.max(filePath.lastIndexOf('/'), filePath.lastIndexOf('\\'));
    const baseName = filePath.slice(lastSlash + 1);
    const dotIndex = baseName.lastIndexOf('.');
    const namePart = dotIndex !== -1 ? baseName.slice(0, dotIndex) : baseName;
    const newFileName = namePart + '-atlas.js';
    const newFilePath = lastSlash !== -1 ? filePath.slice(0, lastSlash + 1) + newFileName : newFileName;

    // Since we cannot actually write to disk, we simply return the path and the cleaned content.
    // In a real environment, you would write `cleanedContent` to `newFilePath` here.

    return { success: true, result: { path: newFilePath, content: cleanedContent } };
  } catch (e) {
    return { success: false, error: e.message };
  }
}

