function execute_sanitize_file_path(params) {
  try {
    if (!params || typeof params.input !== 'string') {
      return { success: false, error: 'Invalid input' };
    }
    const input = params.input;
    // Extract a Windows‑style file path from the input
    const match = input.match(/([A-Za-z]:\\[^\\\s]+(?:\\[^\\\s]+)*)/);
    if (!match) {
      return { success: false, error: 'No path found' };
    }
    let path = match[1];
    // Normalize separators and remove duplicate dashes
    path = path.replace(/\\/g, '/');
    path = path.replace(/---/g, '-');
    return { success: true, result: path };
  } catch (e) {
    return { success: false, error: e.message || 'Error' };
  }
}
